import React, { ReactNode } from 'react';
import { motion } from 'framer-motion';
import AnimatedText from './AnimatedText';

interface AnimatedListProps {
  items: ReactNode[];
  className?: string;
  itemClassName?: string;
  staggerDelay?: number;
  staggerVariation?: number;
  onAnimationComplete?: () => void;
}

/**
 * AnimatedList - A component that animates a list of items with a strictly sequential effect
 * Ensures that each item only starts animating after the previous one is complete
 */
const AnimatedList: React.FC<AnimatedListProps> = ({
  items,
  className = '',
  itemClassName = '',
  staggerDelay = 0.03,
  staggerVariation = 0, // Not used anymore but kept for API compatibility
  onAnimationComplete
}) => {
  // Container animation variant with strict staggering
  const container = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        delayChildren: 0.05,
        staggerChildren: staggerDelay,
        when: 'beforeChildren',
      }
    }
  };

  // Item animation variant with strict sequential timing
  const item = {
    hidden: { opacity: 0, y: 3 },
    visible: { 
      opacity: 1,
      y: 0,
      transition: { 
        duration: 0.15, 
        ease: "easeOut"
      }
    }
  };

  // Convert each item to handle both string and ReactNode
  const processItem = (content: ReactNode, index: number) => {
    // For string content, wrap in AnimatedText
    if (typeof content === 'string') {
      return <AnimatedText key={index} text={content} />;
    }

    // If it's already a React element, return it
    return content;
  };

  return (
    <motion.ul
      className={className}
      variants={container}
      initial="hidden"
      animate="visible"
      onAnimationComplete={onAnimationComplete}
      style={{ 
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'flex-start',
        padding: 0,
        margin: 0,
        listStyle: 'none'
      }}
    >
      {items.map((itemContent, index) => (
        <motion.li 
          key={index}
          className={itemClassName}
          variants={item}
          style={{ width: '100%', justifyContent: 'flex-start' }}
        >
          {processItem(itemContent, index)}
        </motion.li>
      ))}
    </motion.ul>
  );
};

export default AnimatedList;
